INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der CIO immer auch der technische Leiter?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Strategie, nicht Technik"}, {"text": "Ja", "correct": false, "because": "Rollen können getrennt sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptaufgabe hat ein CIO?', 3, '[{"text": "IT-Strategie entwickeln", "correct": true, "because": "Aligns IT mit Geschäftszielen"}, {"text": "Server warten", "correct": false, "because": "Operative Aufgabe"}, {"text": "Code schreiben", "correct": false, "because": "Entwickleraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortlichkeiten gehören zum CIO?', 5, '[{"text": "IT-Budgetplanung", "correct": true, "because": "Ressourcenmanagement"}, {"text": "Datensicherheitsstrategie", "correct": true, "because": "Risikominimierung"}, {"text": "Hardware-Reparatur", "correct": false, "because": "Technikeraufgabe"}, {"text": "Softwaretests", "correct": false, "because": "Entwicklungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der CIO entscheidet über IT-Investitionen. b) Er führt tägliche Backups durch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups sind operativ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit eines CIO?', 4, '[{"text": "Geschäftsziele", "correct": false, "because": "Müssen mit IT abgestimmt sein"}, {"text": "IT-Trends", "correct": false, "because": "Wichtig für Strategie"}, {"text": "Tägliche Netzwerkwartung", "correct": true, "because": "Operative Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein CIO auch für die IT-Sicherheit verantwortlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der strategischen Planung"}, {"text": "Nein", "correct": false, "because": "Nicht nur Technikeraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der CIO bei Projekten?', 3, '[{"text": "Überwacht IT-Ausrichtung", "correct": true, "because": "Sichert Unternehmensziele"}, {"text": "Installiert Software", "correct": false, "because": "Operative Aufgabe"}, {"text": "Kauft Hardware", "correct": false, "because": "Einkaufsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein CIO?', 5, '[{"text": "Risikomanagement", "correct": true, "because": "Schützt IT-Infrastruktur"}, {"text": "Technologieeinführung", "correct": true, "because": "Fördert Innovation"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Ebene"}, {"text": "User-Support", "correct": false, "because": "Helpdesk-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der CIO berichtet an den CEO. b) Er ist für Hardware-Entwicklung zuständig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Herstelleraufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für einen CIO unwichtig?', 4, '[{"text": "IT-Kostenoptimierung", "correct": false, "because": "Teil der Budgetplanung"}, {"text": "Cybersecurity-Richtlinien", "correct": false, "because": "Schutz essenziell"}, {"text": "Tägliche Systemwartung", "correct": true, "because": "Operative Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Entscheidet der CIO über Softwarelizenzen?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der strategischen Planung"}, {"text": "Nein", "correct": false, "because": "Nicht nur Einkauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche überwacht ein CIO?', 4, '[{"text": "IT-Infrastruktur", "correct": true, "because": "Sichert Betrieb"}, {"text": "Datenmanagement", "correct": true, "because": "Wichtig für Compliance"}, {"text": "Hardware-Reparaturen", "correct": false, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der CIO nur für große Firmen relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs brauchen IT-Strategie"}, {"text": "Ja", "correct": false, "because": "Skalierbar relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich als CIO?', 3, '[{"text": "Geschäfts-IT-Abstimmung", "correct": true, "because": "Kern der Rolle"}, {"text": "Schnelle Hardware-Updates", "correct": false, "because": "Operative Ebene"}, {"text": "Niedrige IT-Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der CIO plant Digitalisierung. b) Er behebt Netzwerkausfälle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle sind technisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein guter CIO?', 5, '[{"text": "Effiziente IT-Nutzung", "correct": true, "because": "Optimiert Prozesse"}, {"text": "Innovationsförderung", "correct": true, "because": "Treibt Technologie voran"}, {"text": "Schnelle Fehlerbehebung", "correct": false, "because": "Operative Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für einen CIO irrelevant?', 3, '[{"text": "IT-Risiken", "correct": false, "because": "Muss gemanagt werden"}, {"text": "Technologiestrategie", "correct": false, "because": "Kernaufgabe"}, {"text": "Tägliche Backup-Checks", "correct": true, "because": "Technische Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der CIO auch für den Datenschutz zuständig?', 3, '[{"text": "Ja", "correct": true, "because": "Teil der IT-Strategie"}, {"text": "Nein", "correct": false, "because": "Nicht nur DPO"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein CIO mit externen Partnern verhandelt?', 2, '[{"text": "Ja", "correct": true, "because": "Für IT-Dienstleistungen"}, {"text": "Nein", "correct": false, "because": "Teil der Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entscheidung trifft ein CIO typischerweise?', 4, '[{"text": "Cloud-Strategie", "correct": true, "because": "Langfristige IT-Planung"}, {"text": "Router-Konfiguration", "correct": false, "because": "Technische Ebene"}, {"text": "Patch-Installation", "correct": false, "because": "Operativ"}]');
